#include "h3/renderer.hpp"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
namespace h3 {
void Desktop::kingdomPreview(const std::filesystem::path&directory,const std::filesystem::path&campaign){
 auto check=[](bool b,const char*m){if(!b)throw std::runtime_error(m);};std::filesystem::create_directories(directory);saveDir_=directory/"test-saves";SDL_SetWindowSize(window_,1280,800);settings_=ClientSettings{};settings_.hdArtwork=false;fixedAnimationTime_=1000;scenarioFaction_=0;int index=0;for(auto&e:mapLibrary_["entries"]){if(e["id"]=="seven-lakes-1")break;++index;}selectMap(index);startScenario();check(scene==Scene::Adventure&&game.imported(),"Kingdom original start failed");int first=game.activeHeroId;auto initial=game.hero.pos;camX_=initial.x+.5f;camY_=initial.y+.5f;zoom_=1;
 auto shot=[&](const char*name){toastUntil_=0;render();check(screenshot(directory/(std::string(name)+".png")),"Kingdom screenshot failed");};shot("kingdom-original-start");
 Point next;bool found=false;for(int dy=-1;dy<=1&&!found;++dy)for(int dx=-1;dx<=1&&!found;++dx){Point p{initial.x+dx,initial.y+dy};if(game.canStep(initial,p)&&!game.objectAt(p)&&!game.guardingMonster(p)){next=p;found=true;}}check(found,"No starting departure");render();click(mapScreen(next),false);key(SDLK_m,KMOD_NONE);for(int i=0;i<5&&marching_;++i){fixedAnimationTime_=*fixedAnimationTime_+100000;tick();}check(game.hero.pos==next,"UI could not leave town for recruitment");key(SDLK_t,KMOD_NONE);townBuilding(Tavern);check(scene==Scene::Tavern,"Town tavern did not open");shot("kingdom-tavern-before");int gold=game.resources[Gold];click({180,475},false);check(game.ownedHeroes().size()==2&&game.resources[Gold]==gold-2500,"Tavern UI failed paid recruitment");shot("kingdom-tavern-recruited");key(SDLK_ESCAPE,KMOD_NONE);key(SDLK_ESCAPE,KMOD_NONE);check(scene==Scene::Adventure,"Tavern return failed");int second=game.ownedHeroes().back();key(SDLK_n,KMOD_NONE);check(game.activeHeroId==second&&game.hero.pos==initial,"Next-hero control did not select independent hero");shot("kingdom-second-hero");render();click(mapScreen(next),false);check(scene==Scene::Meeting&&meetingHero_==first,"Adjacent heroes did not open meeting");int total=armyCount(game.hero.army)+armyCount(game.heroes[first].value.army);render();click({180,201},false);render();click({540,201},false);check(armyCount(game.hero.army)+armyCount(game.heroes[first].value.army)==total,"Meeting UI created soldiers");shot("kingdom-meeting-transfer");key(SDLK_ESCAPE,KMOD_NONE);activateHero(first);check(game.activeHeroId==first&&game.hero.pos==next,"First hero was not preserved");shot("kingdom-first-hero-restored");
 bool completed=false;if(!campaign.empty()){std::string error;check(game.load(campaign,error),"Completed original-map save failed to load");check(game.scenarioId=="seven-lakes-1"&&game.result==1,"UI completion used a substitute map or unfinished state");scene=Scene::Journal;journalPage_=0;shot("kingdom-original-story-journal");check(game.scenarioRules["journal"].size()>20,"Full campaign omitted original stories");scene=Scene::Adventure;camX_=game.hero.pos.x+.5f;camY_=game.hero.pos.y+.5f;settle();check(scene==Scene::Outcome,"Actual downloaded-map result did not open victory screen");shot("kingdom-downloaded-map-victory");key(SDLK_RETURN,KMOD_NONE);check(scene==Scene::Menu,"Original-map victory could not be acknowledged");shot("kingdom-victory-acknowledged");completed=true;}
 std::ofstream(directory/"kingdom-ui-audit.json")<<nlohmann::json{{"paidTavernRecruitment",true},{"independentHeroPositions",true},{"nextHeroSelection",true},{"meetingConservesSoldiers",true},{"originalDownloadedMapVictoryDisplayed",completed},{"isolatedSaves",true}}.dump(2)<<'\n';std::cout<<"Multihero, tavern, meeting and original-map outcome passed\n";
}
}
